import re

def file_name_check(file_name):
    pattern = r'^[a-zA-Z][a-zA-Z0-9]{0,}(\.[a-zA-Z0-9]{1,}){1}$'
    match = re.match(pattern, file_name)
    if match:
        name_parts = file_name.split('.')
        if len(name_parts) == 2 and name_parts[1] in ['txt', 'exe', 'dll']:
            digit_count = sum(c.isdigit() for c in file_name)
            if digit_count <= 3:
                return 'Yes'
    return 'No'

