import re

def file_name_check(file_name):
    pattern = r'^[a-zA-Z][a-zA-Z0-9]{0,}(\d{0,3})\.(txt|exe|dll)$'
    match = re.match(pattern, file_name)
    if match:
        digit_count = len(match.group(1))
        if digit_count <= 3:
            return 'Yes'
    return 'No'

